125	                                const std::vector<std::pair<std::string, std::any>>& kwargs,
126	                                const std::string& op_name) {
127	  CHECK(args.size() == 3 || args.size() == 4)
128	      << "The operator " << op_name << " requires 3 arguments (acc, lhs, rhs) or 4 with the optional "
129	      << "init_cond predicate, but got " << args.size();
130	  CheckMatmulInitCond(args, 3, op_name);
131	
132	  // All arguments must be TileType
133	  auto acc_type = As<TileType>(args[0]->GetType());
134	  auto lhs_type = As<TileType>(args[1]->GetType());
135	  auto rhs_type = As<TileType>(args[2]->GetType());
136	
137	  CHECK(acc_type) << "The operator " << op_name << " requires first argument (acc) to be a TileType, but got "
138	                  << args[0]->GetType()->TypeName();
139	  CHECK(lhs_type) << "The operator " << op_name
140	                  << " requires second argument (lhs) to be a TileType, but got "
141	                  << args[1]->GetType()->TypeName();
142	  CHECK(rhs_type) << "The operator " << op_name << " requires third argument (rhs) to be a TileType, but got "
143	                  << args[2]->GetType()->TypeName();
144	
145	  auto geometry = DeduceMatmulProductInfo(lhs_type, rhs_type, op_name);
146	  const auto& acc_shape = acc_type->shape_;
147	
148	  CHECK(acc_shape.size() == 2) << "The operator " << op_name << " requires acc to be 2D, but got "
149	                               << acc_shape.size() << " dimensions";
150	
151	  // Matrix multiplication with accumulation: acc[M, N] += lhs[M, K] @ rhs[K, N].
152	  // Match the logical valid rectangle, not padding in the boxed allocations.
153	  const auto acc_valid = GetValidShape(acc_type);
154	  const ExprPtr& m_dim_acc = acc_valid[0];
155	  const ExprPtr& n_dim_acc = acc_valid[1];
156	
157	  // The aliased Acc result must agree with the matrix product's physical M/N.
158	  // Valid windows are checked separately below and may be narrower.
159	  auto physical_m_acc_const = As<ConstInt>(acc_shape[0]);
160	  auto physical_m_product_const = As<ConstInt>(geometry.physical_shape[0]);
161	  auto physical_n_acc_const = As<ConstInt>(acc_shape[1]);
162	  auto physical_n_product_const = As<ConstInt>(geometry.physical_shape[1]);
163	
164	  if (physical_m_acc_const && physical_m_product_const) {
165	    CHECK(physical_m_acc_const->value_ == physical_m_product_const->value_)
166	        << "The operator " << op_name
167	        << " requires matching physical M dimensions, but got acc M=" << physical_m_acc_const->value_
168	        << " and product M=" << physical_m_product_const->value_;
169	  }
170	  if (physical_n_acc_const && physical_n_product_const) {
171	    CHECK(physical_n_acc_const->value_ == physical_n_product_const->value_)
172	        << "The operator " << op_name
173	        << " requires matching physical N dimensions, but got acc N=" << physical_n_acc_const->value_
174	        << " and product N=" << physical_n_product_const->value_;
175	  }
176	
177	  // PTO derives the computed M/K/N rectangle from lhs/lhs/rhs. The in-place
178	  // accumulator and rhs K window may be larger, but must contain that complete
179	  // rectangle. Unknown symbolic relations remain legal, matching the previous
180	  // static-only validation while rejecting every provably out-of-bounds case.
181	  CHECK(ProveValidExtentLessEqual(geometry.valid_shape[0], m_dim_acc) != ProofResult::kFalse)
182	      << "The operator " << op_name
183	      << " requires acc valid M to cover lhs valid M, but got acc M=" << PythonPrint(m_dim_acc)
184	      << " and lhs M=" << PythonPrint(geometry.valid_shape[0]);
185	  CHECK(ProveValidExtentLessEqual(geometry.valid_shape[1], n_dim_acc) != ProofResult::kFalse)
186	      << "The operator " << op_name
187	      << " requires acc valid N to cover rhs valid N, but got acc N=" << PythonPrint(n_dim_acc)
188	      << " and rhs N=" << PythonPrint(geometry.valid_shape[1]);
189	
190	  CHECK(acc_type->dtype_ == geometry.accumulator_dtype)
191	      << "The operator " << op_name << " requires accumulator dtype " << geometry.accumulator_dtype.ToString()
192	      << ", but got " << acc_type->dtype_.ToString();
193	
194	  // The output aliases the accumulator's physical storage and valid region.
195	  std::vector<ExprPtr> output_shape = acc_shape;
196	
197	  // Acc layout (Nz) — as in tile.matmul, from the destination's implicit layout.
198	  TileView tile_view;
199	  tile_view_semantics::SetTileLayout(
200	      tile_view, tile_view_semantics::GetImplicitTileLayout(output_shape, MemorySpace::Acc));
201	  tile_view.valid_shape = acc_valid;
202	  // Inherit the accumulator's compact mode rather than re-deriving it. This op
203	  // is `set_output_reuses_input(0)`: the result *is* the accumulator's buffer,
204	  // and codegen only aliases the two when their `TileBufSignature` — compact
205	  // included — matches, so inheriting keeps that alias legal by construction.
206	  // `tile.matmul` is where the accumulator's stride is established, so it is
207	  // the only place that derives compact from the valid rows (#2470).
208	  tile_view.compact = tile_view_semantics::GetEffectiveTileView(*acc_type).compact;
209	
210	  return std::make_shared<TileType>(output_shape, geometry.accumulator_dtype, std::nullopt, tile_view,
211	                                    MemorySpace::Acc);
212	}
