125	// Mirror AreExprsEqual: ConstInt nodes compare by value, binary ops, unary ops
126	// and Call nodes compare structurally (kind + operands / kind + dtype + operand /
127	// op + args), all others by pointer identity.  The hash must match this
128	// granularity — any extension to AreExprsEqual MUST get a corresponding branch
129	// here.
130	inline uint64_t HashExprForAreExprsEqual(const ExprPtr& e) {
131	  if (!e) return 0;
132	  if (auto c = As<ConstInt>(e)) {
133	    return hash_combine(kConstIntHashTag, std::hash<int64_t>{}(c->value_));
134	  }
135	  if (auto b = As<BinaryExpr>(e)) {
136	    uint64_t h = hash_combine(kBinaryExprHashTag, static_cast<uint64_t>(e->GetKind()));
137	    h = hash_combine(h, HashExprForAreExprsEqual(b->left_));
138	    return hash_combine(h, HashExprForAreExprsEqual(b->right_));
139	  }
140	  if (auto u = As<UnaryExpr>(e)) {
141	    // AreExprsEqual compares a unary node's kind, result dtype and operand, so
142	    // all three have to reach the hash or two equal TileViews could land in
143	    // different buckets.
144	    uint64_t h = hash_combine(kUnaryExprHashTag, static_cast<uint64_t>(e->GetKind()));
145	    auto scalar = std::dynamic_pointer_cast<const ScalarType>(e->GetType());
146	    h = hash_combine(h, scalar ? static_cast<uint64_t>(scalar->dtype_.Code()) : 0);
147	    return hash_combine(h, HashExprForAreExprsEqual(u->operand_));
148	  }
149	  if (auto call = As<Call>(e)) {
150	    uint64_t h = hash_combine(kCallExprHashTag, std::hash<std::string>{}(call->op_ ? call->op_->name_ : ""));
151	    for (const auto& arg : call->args_) {
152	      h = hash_combine(h, HashExprForAreExprsEqual(arg));
153	    }
154	    return h;
155	  }
156	  return hash_combine(kExprPtrHashTag, std::hash<const void*>{}(e.get()));
157	}
