161	size_t Hash(const TileView& tv) {
162	  uint64_t h = 0;
163	  h = hash_combine(h, tv.valid_shape.size());
164	  for (const auto& e : tv.valid_shape) h = hash_combine(h, HashExprForAreExprsEqual(e));
165	  h = hash_combine(h, tv.stride.size());
166	  for (const auto& e : tv.stride) h = hash_combine(h, HashExprForAreExprsEqual(e));
167	  h = hash_combine(h, HashExprForAreExprsEqual(tv.start_offset));
168	  h = hash_combine(h, std::hash<int>{}(static_cast<int>(tv.blayout)));
169	  h = hash_combine(h, std::hash<int>{}(static_cast<int>(tv.slayout)));
170	  h = hash_combine(h, std::hash<uint64_t>{}(tv.fractal));
171	  h = hash_combine(h, std::hash<int>{}(static_cast<int>(tv.pad)));
172	  h = hash_combine(h, std::hash<int>{}(static_cast<int>(tv.compact)));
173	  return static_cast<size_t>(h);
174	}
