TensorLayout StringToTensorLayout(const std::string& str) {
  if (str == "ND") {
    return TensorLayout::ND;
  } else if (str == "DN") {
    return TensorLayout::DN;
  } else if (str == "NZ") {
    return TensorLayout::NZ;
  } else if (str == "MX_A_ZZ") {
    return TensorLayout::MX_A_ZZ;
  } else if (str == "MX_B_NN") {
